import pathlib,html
root=pathlib.Path('.')
scenes=[
('01-opening',14,'01 / THE PROBLEM','The dashboard<br>went dark.','opening.png',[(4,'Retrieve earlier usage declarations without the provider’s API.'),(9,'Sumplus Receipt Lens.<br>Built on Arkiv.')]),
('02-clean',24,'02 / INDEPENDENT READ','Query Arkiv<br>directly.','clean.png',[(6,'4 entities. 2 cursor pages.<br>One pinned block.'),(13,'0.060000 USDC<br>Signed declarations, not proven spend.'),(19,'Creator + signature +<br>signed close count agree.')]),
('03-dispute',28,'03 / SOURCE CHECK','Same session.<br>Fake source.','dispute-full.png',[(6,'Matching provider and session fields confer no authority.'),(13,'Creator must match.<br>The payload signature must also verify.'),(20,'Duplicate 3 + missing 2.<br>Review needed. No complete bill.')]),
('04-failure',20,'04 / DEPENDENCIES','No Sumplus<br>backend.','failure.png',[(5,'Static client. Direct public Arkiv RPC.<br>No provider API in the read path.'),(11,'Failed RPC clears results<br>and disables export.'),(16,'No fallback fixtures.<br>The RPC is still a dependency.')]),
('05-custody',20,'05 / RECIPIENT CONTROL','Hand over control.',None,[(5,'Native ownership transfer.<br>Creator and signature still identify the publisher.'),(11,'Old publisher patch + delete: NotOwner.<br>Recipient patch: successful transaction.'),(16,'The recipient can edit or delete.<br>This is user control, not immutable storage.')]),
('06-expiration',20,'06 / ENTITY EXPIRATION','A review window. Not forever.',None,[(5,'Actual short probe: found at block706439, expired706453, absent706460.'),(11,'Creation transaction remains readable.<br>Expired payload is not restored.'),(16,'Initial expiry only. Owners can delete sooner.<br>Export your own evidence copy.')]),
('07-reproduce',14,'07 / REPRODUCE','Inspect it<br>yourself.',None,[(4,'MIT source · arkiv/schema.md · arkiv/friction.md'),(9,'Origin and consistency checked.<br>Real AI usage and payment remain unverified.')])]
css='''@font-face{font-family:Inter;src:url(assets/fonts/inter-latin-400-normal.woff2) format('woff2');font-weight:400}@font-face{font-family:Inter;src:url(assets/fonts/inter-latin-600-normal.woff2) format('woff2');font-weight:600}@font-face{font-family:"IBM Plex Mono";src:url(assets/fonts/ibm-plex-mono-latin-400-normal.woff2) format('woff2');font-weight:400}*{box-sizing:border-box}#root{position:relative;width:100%;height:100%;font-family:Inter,sans-serif;color:#8da4ad;overflow:hidden}.P-bg{position:absolute;inset:0;background:#17262d}.P-content{position:absolute;inset:0}.P-brand{position:absolute;top:55px;left:80px;font:26px "IBM Plex Mono";letter-spacing:3px;color:#d4f19a}.P-demo{position:absolute;top:60px;right:80px;font:19px "IBM Plex Mono";letter-spacing:1px;border:1px solid #8da4ad;padding:10px 14px;color:#8da4ad}.P-kicker{font:24px "IBM Plex Mono";letter-spacing:2px;color:#93cebe;margin-bottom:30px}.P-left{position:absolute;left:80px;top:215px;width:440px}.P-title{font-size:60px;line-height:1.08;letter-spacing:-2px;font-weight:400;color:#d4f19a;margin:0 0 45px}.P-call{font-size:29px;line-height:1.45;margin:24px 0;padding-top:21px;border-top:1px solid #8da4ad55}.P-image{position:absolute;left:560px;top:240px;width:1280px;height:720px;object-fit:contain;object-position:center;border:1px solid #8da4ad55;border-radius:8px;background:#0F221D}.P-image-label{position:absolute;left:560px;top:204px;font:18px "IBM Plex Mono";letter-spacing:1px;color:#93cebe}.P-footer{position:absolute;bottom:35px;left:80px;right:80px;display:flex;justify-content:space-between;font:17px "IBM Plex Mono";color:#8da4ad}.P-wide{position:absolute;left:80px;right:80px;top:230px}.P-wide-title{font-size:80px;color:#d4f19a;line-height:1.06;letter-spacing:-2px;font-weight:400;margin:0 0 48px}.P-contract{display:flex;gap:40px;margin:0 0 30px}.P-card{width:530px;border:1px solid #8da4ad55;border-radius:8px;padding:30px}.P-number{font-size:74px;line-height:1.1;color:#d4f19a}.P-card p{font-size:29px;margin:17px 0 0}.P-wide-call{font-size:34px;line-height:1.4;max-width:1670px;padding-top:20px;margin:20px 0;border-top:1px solid #8da4ad55}.P-url{font:31px "IBM Plex Mono";color:#93cebe;line-height:1.6;overflow-wrap:anywhere;margin-top:20px}.P-version{position:absolute;left:560px;top:975px;font:15px "IBM Plex Mono";color:#8da4ad}'''
for ident,duration,kicker,title,image,calls in scenes:
 cid='s'+ident
 style=css.replace('P-',cid+'-')
 if ident=='03-dispute':style+=f'.{cid}-image{{object-fit:none;object-position:0px -600px}}'
 if ident in ['05-custody','06-expiration']:style+=f'.{cid}-wide{{top:205px}} .{cid}-wide-title{{font-size:64px;margin-bottom:28px}} .{cid}-card{{padding:24px}} .{cid}-number{{font-size:62px}} .{cid}-card p{{font-size:25px}}'
 if image:
  inside=f'<div class="{cid}-left"><div class="{cid}-kicker">{kicker}</div><h1 id="{cid}-title" class="{cid}-title">{title}</h1>'+''.join(f'<p id="{cid}-call-{i}" class="{cid}-call">{text}</p>' for i,(_,text) in enumerate(calls))+'</div>'
  inside+=f'<div class="{cid}-image-label">{('CONTROLLED RPC FAILURE · ACTUAL APP RESPONSE' if ident=='04-failure' else 'ACTUAL APP SCREEN · READY TO QUERY' if ident=='01-opening' else 'ACTUAL CAPTURED TIRAMISU RESULT')}</div><img id="{cid}-plate" class="{cid}-image" src="assets/{image}" alt="Actual synthetic Receipt Lens screen"><div class="{cid}-version">Captured interface. Not an animated simulation of a network request.</div>'
 else:
  inside=f'<div class="{cid}-wide"><div class="{cid}-kicker">{kicker}</div><h1 id="{cid}-title" class="{cid}-wide-title">{title}</h1>'
  if ident=='06-expiration':inside+=f'<div id="{cid}-plate" class="{cid}-contract"><div class="{cid}-card"><div class="{cid}-number">30 days</div><p>Usage entities<br>Prototype bill-review window</p></div><div class="{cid}-card"><div class="{cid}-number">90 days</div><p>Signed close statement<br>Longer dispute reference</p></div></div>'
  elif ident=='05-custody':inside+=f'<div id="{cid}-plate" class="{cid}-contract"><div class="{cid}-card"><div class="{cid}-number">Publisher</div><p>Issues signed statements<br>Transfers native ownership</p></div><div class="{cid}-card"><div class="{cid}-number">Recipient</div><p>Controls records<br>Can export, edit or delete</p></div></div>'
  else:inside+=f'<div id="{cid}-plate" class="{cid}-url">sumplus-real.github.io/sumplus-receipt-lens/<br>github.com/sumplus-real/sumplus-receipt-lens</div>'
  inside+=''.join(f'<p id="{cid}-call-{i}" class="{cid}-wide-call">{text}</p>' for i,(_,text) in enumerate(calls))+'</div>'
 timeline=f'const tl=gsap.timeline({{paused:true}});tl.fromTo("#{cid}-title",{{opacity:0}},{{opacity:1,duration:0.4}},0.05);tl.fromTo("#{cid}-plate",{{opacity:0}},{{opacity:1,duration:0.4}},0.05);'
 for i,(time,text) in enumerate(calls):timeline+=f'tl.fromTo("#{cid}-call-{i}",{{opacity:0}},{{opacity:1,duration:0.35}},{time});'
 timeline+=f'window.__timelines["{ident}"]=tl;'
 content=f'''<template><style>{style}</style><script src="assets/vendor/gsap.min.js"></script><div id="root" data-composition-id="{ident}" data-start="0" data-duration="{duration}" data-width="1920" data-height="1080"><div id="{cid}-background" class="clip {cid}-bg" data-start="0" data-duration="{duration}" data-track-index="0"></div><div id="{cid}-content" class="clip {cid}-content" data-start="0" data-duration="{duration}" data-track-index="1"><div class="{cid}-brand">SUMPLUS / RECEIPT LENS</div><div class="{cid}-demo">SYNTHETIC · TIRAMISU TESTNET</div>{inside}<div class="{cid}-footer"><span>SECURITY + CENSORSHIP RESISTANCE</span><span>Statements ≠ proof of real usage or payment</span></div></div></div><script>{timeline}</script></template>'''
 (root/'compositions/frames'/f'{ident}.html').write_text(content)
p=root/'STORYBOARD.md';s=p.read_text().replace('- status: outline','- status: animated');p.write_text(s)
print('Authored seven evidence-based scenes, total140s; no generated audio or external footage.')

# Assemble a local-only root from the scene order, without CDN dependencies.
slots=[];start=0
for ident,duration,*_ in scenes:
 slots.append(f'<div id="el-{ident}" class="clip scene" data-composition-id="{ident}" data-composition-src="compositions/frames/{ident}.html" data-start="{start}" data-duration="{duration}" data-track-index="1" data-width="1920" data-height="1080"></div>')
 start+=duration
(root/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><script src="assets/vendor/gsap.min.js"></script><style>*{margin:0;padding:0;box-sizing:border-box}html,body{width:100%;height:100%;overflow:hidden;background:#17262d}#root{position:relative;width:100%;height:100%;overflow:hidden}.scene{position:absolute;inset:0;width:100%;height:100%}</style></head><body>'+f'<div id="root" data-composition-id="main" data-start="0" data-duration="{start}" data-width="1920" data-height="1080">'+''.join(slots)+'</div><script>window.__timelines["main"]=gsap.timeline({paused:true});</script></body></html>')
